// ... your JavaScript drawing code here ...

// Example: Draw a simple rectangle
ctx.fillStyle = 'rgba(0, 0, 255, 0.2)';
ctx.fillRect(100, 100, 200, 100);

canvas.height = window.innerHeight;

// ... your JavaScript drawing code here ...

// Example: Draw a simple rectangle
ctx.fillStyle = 'rgba(0, 0, 255, 0.2)';
